public class UrlBuilderTest {

    @Test
    public void newUrlBuilderWithProtocolAndHost_EmptyQueryAndFragment() throws MalformedURLException, URISyntaxException {
        URL url = new URL("http://example.com");
        UrlBuilder builder = new UrlBuilder(url);
        assertEquals("http://example.com", builder.u.getProtocol());
        assertEquals("example.com", builder.u.getHost());
    }

    @Test
    public void newUrlBuilderWithProtocolAndHost_PunnyCoding() throws MalformedURLException, URISyntaxException {
        URL url = new URL("http://example.com");
        UrlBuilder builder = new UrlBuilder(url);
        assertEquals("http://example.com", builder.u.getProtocol());
        assertEquals("example.com", builder.u.getHost());
    }

    @Test
    public void newUrlBuilderWithQueryAndFragment_EmptyQueryAndFragment() throws MalformedURLException, URISyntaxException {
        URL url = new URL("http://example.com?query=string&fragment#ref");
        UrlBuilder builder = new UrlBuilder(url);
        assertEquals("http://example.com", builder.u.getProtocol());
        assertEquals("example.com", builder.u.getHost());
    }

    @Test
    public void newUrlBuilderWithQueryAndFragment_PunnyCoding() throws MalformedURLException, URISyntaxException {
        URL url = new URL("http://example.com?query=string&fragment#ref");
        UrlBuilder builder = new UrlBuilder(url);
        assertEquals("http://example.com", builder.u.getProtocol());
        assertEquals("example.com", builder.u.getHost());
    }

    @Test
    public void build_urlBuilderWithEmptyQueryAndFragment_ReturnsUrlWithoutPunyCoding() throws MalformedURLException, URISyntaxException {
        URL url = new UrlBuilder(new URL("http://example.com"));
        assertNotEquals(null, url);
    }

    @Test
    public void appendKeyVal_toExistingQ_UsesExistingQ() {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com?query=string"));
        builder.appendKeyVal(kv);
        assertTrue(builder.q != null && builder.q.toString().equals("key=value&query=string"));
    }

    @Test
    public void appendKeyVal_toExistingQ_appendsKeyAndValue() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        UrlBuilder builder = new UrlBuilder(new URL("http://example.com?query=string"));
        builder.appendKeyVal(kv);
        assertTrue(builder.q != null && builder.q.toString().equals("key=value&query=string"));
    }

    @Test
    public void appendKeyVal_toNewQCreatesNewQ() throws UnsupportedEncodingException {
        Connection.KeyVal kv = new Connection.KeyVal("key", "value");
        UrlBuilder builder = new UrlBuilder(new URL());
        String q = "{}";
        builder.q = StringUtil.borrowBuilder().append(q);
        builder.appendKeyVal(kv);
        assertTrue(builder.q != null && builder.q.toString().equals("{}&key=value"));
    }

    @Test
    public void decodePart_emptyString_ReturnsEmptyString() {
        assertEquals("", UrlBuilder.decodePart(""));
    }

    @Test
    public void decodePart_nonASCIIString_ReturnsNonASCIIString() throws UnsupportedEncodingException {
        assertEquals("ä", UrlBuilder.decodePart("ä"));
    }

    @Test
    public void normalizeQuery_replacesSpacesWithPlusSigns() {
        String q = "query string";
        String expected = "query%20string";
        assertEquals(expected, UrlBuilder.normalizeQuery(q));
    }

    @Test
    public void normalizeRef_replacesSpacesWithPercent20Signs() {
        String r = "ref string";
        String expected = "%20ref%20string";
        assertEquals(expected, UrlBuilder.normalizeRef(r));
    }
}
